from pathlib import Path
import json
P=Path('knowledge');refs=json.loads((P/'upstream-docs/manifest.json').read_text(encoding='utf-8'))
# Original task summaries, linked to their reviewed upstream reference.
rows=[
(0,'register','Registry and register concepts','Understand registries and registers','A registry is the application for a domain; a register is a structured dataset inside it.','Identify the correct registry service.\nChoose the register that stores the required entity.\nCheck related records and linked identifiers before entering data.','Existing registry access.','Open the relevant intake or record screen.','Different registers have different fields; do not treat a household and a person as the same record.'),
(1,'register','Proposed and approved changes','Understand proposed and approved record changes','A proposed change is separate from the approved record until its workflow completes.','Open the record and identify the section to change.\nDescribe the proposed correction and attach required evidence.\nSubmit through the configured review process.\nCheck the request status before assuming the live record changed.','Record editing permission and evidence.','Track verification and approval.','A saved proposal does not by itself prove that the approved record has changed.'),
(2,'register','Workflow audit','Read the record workflow audit','Workflow evidence and actor timestamps explain who initiated, checked and approved a change.','Locate the change request for the record.\nReview the submitted evidence and recorded actors.\nCompare the decision and time with the reported issue.','Permission to view the request and audit information.','Escalate discrepancies with the request reference.','A workflow trail differs from a snapshot of the record at a particular time.'),
(3,'register','Record documents','Attach and review record documents','Record file fields and evidence attached to a change request serve different purposes.','Check the file field label, allowed type and maximum size.\nUpload the required file into its intended slot.\nConfirm it appears before saving or submitting.\nUse the view control to inspect the file when reviewing evidence.','Document access and the required file.','Submit the proposed record or change for review.','Supporting evidence on a change request may not become a permanent record file after approval.'),
(4,'register','Ingestion monitoring','Monitor imported registry submissions','Partner and staff ingestion can create intake submissions or proposed updates.','Identify the source, target register and intake form.\nRetain the returned correlation reference.\nCheck classification, transformation and processing status where available.\nInvestigate failed items before resubmitting.','An authorised integration and supported ingestion configuration.','Verify the resulting submission or change request.','Acceptance by an API is not proof of successful registry processing; do not repeatedly send the same payload.'),
(5,'register','Committed record history','Inspect committed record history','Record history shows approved snapshots and associated changes.','Open Version History if it is available on the record.\nChoose the relevant date.\nCompare the changed sections and linked request.','History viewing permission.','Use the evidence for an authorised correction or investigation.','History, workflow audit and computed-score history are different views; availability depends on the installed release.'),
(6,'register','Registry intake lifecycle','Follow the registry intake lifecycle','Intake progresses from a saved form through submission, review and backend processing.','Choose the target register and intake form.\nComplete required fields and save a draft.\nSubmit and retain the application reference.\nTrack review and processing separately.','Configured intake form and intake access.','Verify that processing completed and the record exists.','Submitted forms may be locked. Approval and successful backend processing are separate milestones.'),
(7,'consent-manager','Consent-aware sharing','Understand consent-aware registry sharing','Documented sharing separates the consent decision from enforcement by the registry.','Identify the recipient, purpose and requested data.\nCheck the applicable consent and partner policy.\nUse the authorised integration to request only the effective permitted fields.','Configured consent enforcement and an authorised recipient.','Record the decision reference or resolve a denial.','Documentation does not prove that every connector in this sandbox enforces the same consent flow.'),
(8,'register','Duplicate candidate review','Review potential duplicate registry records','Deduplication produces candidates according to configured fields and matching rules.','Check whether deduplication is enabled for the register.\nReview the flagged candidates and supporting identity data.\nEscalate uncertain matches through the authorised workflow.','Duplicate-review access and configured matching rules.','Record the reviewed outcome through available controls.','A similarity score is a review signal, not proof that two people are the same. Administrators control thresholds.'),
(9,'iam-staff-ui','Operations and configuration roles','Understand role-based access','Operational and configuration permissions are assigned through the identity system.','Identify the task and its required permission.\nCheck the assigned application and account role.\nAsk the access administrator to resolve a missing permission.','Existing identity and access administration process.','Sign in again after an approved role change.','Default upstream role names may differ from NigeriaG2P roles. Choosing a persona does not grant access.'),
(10,'register','Registry export jobs','Understand registry export jobs','Documented export jobs can include a chosen register and related records.','Confirm the filtered or selected scope.\nChoose an available export format.\nMonitor the job in export history.\nCheck the downloaded file and related-record coverage.','Export permission; the export feature must exist in the installed release.','Handle the output using the approved reporting process.','A retry may use current filters rather than the previous row selection. Check scope before retrying.'),
(11,'pbms','Eligibility and entitlement rules','Distinguish programme processing rules','Eligibility, disbursement selection and entitlement are separate rule decisions.','Identify which decision is being configured.\nUse the programme-approved criteria for that decision.\nTest with fictional examples and inspect the resulting status.','Programme management permission and approved rule definitions.','Send the result through configured verification.','Do not infer benefit amounts from eligibility alone; missing or stale registry data can affect results.'),
(12,'pbms','Enrolment and disbursement cycles','Distinguish enrolment and disbursement cycles','Enrolment cycles select beneficiaries; disbursement cycles organise delivery of benefits.','Select the programme and identify the cycle type.\nCheck its dates and source beneficiary list.\nApply the configured rules and review the resulting list.','Programme access and configured cycles.','Follow the relevant list verification process.','Newer PBMS documentation describes dual cycles; verify the controls present in this installation.'),
(13,'pbms','List verification','Review programme lists before finalisation','Configured verifications provide evidence and accountability before a list is finalised.','Open the relevant enrolment or disbursement list.\nCheck the required verification stage.\nReview the supporting information and record your authorised assessment.','Assigned verification permission.','Send the list to the next configured reviewer.','Do not claim a list is verified simply because it has been generated.'),
(14,'pbms','Registry-based list corrections','Correct the source of beneficiary lists','Documented PBMS list generation uses registry data as its source.','Identify the incorrect source record.\nCorrect it through the registry workflow.\nConfirm the approved change before generating a replacement list where permitted.','Registry correction and programme permissions.','Review the regenerated list and its cycle state.','Approved cycles may prevent new lists. Do not edit exported lists to simulate a registry correction.'),
(15,'pbms','Bank reconciliation concepts','Understand bank reconciliation','Reconciliation compares disbursement references with bank transaction evidence.','Check the programme, cycle and disbursement reference.\nReview the returned transaction or statement evidence in the configured reconciliation service.\nEscalate unmatched or inconsistent items.','A configured reconciliation integration and assigned staff permission.','Record the resolved reconciliation result.','The upstream guide describes sponsor-bank statements and Bridge processing. This sandbox does not issue real payments.'),
(16,'superset','Programme reporting','Use programme reports and dashboards','Programme reporting can cover beneficiary statistics, transactions and reconciliation.','Open the relevant dashboard.\nConfirm its dataset, period and programme filters.\nCheck whether its numbers represent people, households, applications or transactions.','Dashboard viewing permission and a configured dataset.','Use the filtered results in authorised reporting.','A dashboard may not refresh immediately when source records change; check its update time.'),
(17,'pbms','Programme fund records','Understand programme fund records','A programme fund records an allocation against the chosen programme and company.','Open programme accounting if available.\nCheck the programme, company, date and amount on the fund record.\nFollow the finance team’s authorised process for any proposed allocation.','Finance authority and the relevant accounting feature.','Review the allocation using the programme finance workflow.','Examples in upstream documentation do not define NigeriaG2P budgets or authorise a transfer. Use fictional amounts in the sandbox.'),
(18,'pbms','Cycle manager configuration','Review cycle manager settings','A cycle manager defines the configured behaviour of programme benefit cycles.','Open the programme configuration.\nInspect its cycle manager and available settings.\nConfirm the intended cycle behaviour with the programme owner before changing it.','Programme configuration authority.','Test the configuration using a demonstration cycle.','Older cycle-manager screens differ from newer PBMS. Do not enable automatic approval without an approved policy.'),
(19,'registry','Individual registrant entry','Create an individual registrant in the legacy registry','Legacy registry screens collect a person’s identifying and personal details.','Open Registry and choose Individual.\nUse Create if your account has the required permission.\nEnter the mandatory names and the configured personal details.\nReview and save the record.','Registrar access and the information required by the form.','Link the person to the correct household or programme as required.','This guide applies to the legacy registry; modern intake uses a different review workflow. Use fictional identities here.'),
(20,'registry','Household membership entry','Link members to a household or group','Legacy groups can link existing individual registrants as members.','Open the group or household.\nUse the Members section to select existing individuals.\nCheck each person and membership relationship.\nReview and save the proposed membership.','Group-editing permission and the member records.','Check the saved membership and any applicable review status.','A person’s name alone is insufficient to identify the correct record; compare the authorised identifiers.'),
(21,'registry','Identifier type configuration','Maintain configured identifier types','Identifier types define the options used when storing registrant IDs.','Open registry configuration if authorised.\nInspect existing ID Types before proposing a new one.\nUse the approved identifier name and save through the available process.','Registry configuration authority.','Use the configured type when entering an identifier.','An identifier type is a label and does not by itself verify a NIN or other identity.'),
(22,'registry','Relationship type configuration','Maintain relationship definitions','Relationships can define source and destination entity types and an inverse label.','Review existing relationship definitions.\nConfirm the intended direction and entity types.\nEnter the approved name and inverse name where the form requires them.','Registry configuration authority.','Test the relationship on fictional records.','Membership and relationship definitions must match the intended household model; do not create duplicate labels.'),
(23,'registry','CSV import validation','Validate a CSV import before loading','Legacy import maps spreadsheet columns to registry fields.','Choose the correct register and Import records if available.\nUpload a fictional test file.\nMap each column to its intended field.\nRun Test and resolve errors before Import.','Import permission and a correctly formatted file.','Check imported records, IDs and relationships.','A successful file upload does not validate mappings. Retain identifiers to avoid accidental duplicate imports.'),
(24,'pbms','Proxy means test configuration','Understand proxy means test configuration','A PMT combines configured household indicators and weights for programme assessment.','Open the programme’s PMT configuration where available.\nCompare fields and weights with the approved scoring specification.\nTest expected outcomes with fictional household examples.','Programme configuration authority and approved scoring rules.','Review the results before applying the programme process.','The library supplies no Nigerian eligibility threshold. AI must not invent weights, cutoffs or policy rules.'),
(25,'pbms','Eligibility reassessment','Understand eligibility reassessment','Older PBMS supports reassessing enrolled registrants against updated configured criteria.','Confirm the programme and reason for reassessment.\nReview the approved criteria and current enrolled list.\nUse Verify eligibility only through the authorised programme process.\nCheck resulting beneficiary statuses.','Programme management authority and existing enrolled records.','Review any changed status and communicate through the approved process.','Reassessment can affect beneficiary status; do not run it casually or treat a draft registrant as enrolled.'),
(26,'pbms','Programme duplicate checks','Check programme duplicate status','Programme deduplication uses the programme’s configured deduplication manager.','Open the programme and inspect its beneficiaries.\nReview the configured duplicate-check rules.\nRun the available check only when authorised and inspect flagged statuses.','Programme administration permission.','Investigate candidate duplicates before the next programme step.','A Duplicated status requires review; do not delete or merge records solely on a matching name.'),
(27,'pbms','Enrolment outcomes','Interpret programme enrolment results','Configured programme criteria determine which draft candidates become enrolled.','Open the programme and inspect candidate statuses.\nConfirm the applicable eligibility configuration.\nUse the authorised enrolment workflow.\nReview Enrolled and Not Eligible results.','Programme management permission and candidate records.','Continue to the configured verification or benefit cycle.','Registration, eligibility and enrolment are distinct states; an application is not a payment confirmation.'),
(28,'pbms','Entitlement assessment stages','Understand staged entitlement assessment','Older PBMS can assign entitlement assessment to multiple managers in sequence.','Check the programme’s assessment stage and your assignment.\nReview evidence and record the assessment required at your stage.\nSubmit through the configured entitlement workflow.','Configured staged assessment and the appropriate manager role.','Allow the next authorised stage to review the assessment.','Only assigned stages can carry out their actions. An assessment recommendation is not an approved payment.'),
(29,'portal-admin','Programme notifications','Review programme notification configuration','A notification manager connects programme events to configured notification behaviour.','Open the programme configuration.\nInspect the assigned notification manager and provider type.\nConfirm permitted templates and recipient behaviour using fictional test data.','Programme configuration permission and an enabled provider.','Check the test notification outcome.','A configured manager does not prove delivery. Avoid sending live messages during a client demonstration.'),
(30,'odk','ODK import field mapping','Map field collection data into the registry','An ODK importer transforms selected submission fields into individual or group records.','Identify the ODK form and target registry.\nCheck that the form has its intended importer and field mapping.\nTest a fictional submission and inspect the transformed values.','ODK/import administration access and a supported mapping configuration.','Validate the imported record and its processing status.','Mappings are form-specific. An ODK submission is not automatically a verified beneficiary.'),
(31,'portal-admin','Social registry data source','Understand importing a registry data source into PBMS','Legacy PBMS can use configured data sources to retrieve social registry records.','Check the source service and the target individual or group register.\nHave the authorised administrator confirm endpoint and authentication configuration.\nTest a small fictional dataset and check field mapping.','Approved integration access and a configured data source.','Verify imported records before programme processing.','Do not place passwords or tokens in knowledge content. Source and target identifiers must remain consistent.'),
(32,'iam-staff-ui','Application and login provider configuration','Understand application and login-provider administration','The IAM admin console describes registered applications and their login providers.','Open Applications to inspect the service’s registered URL and identifier.\nReview the associated Login Providers.\nEscalate an incorrect mapping to the authorised access administrator.','IAM administration access.','Test the existing sign-in route after an approved correction.','Application registration and persona selection are separate from operational permission assignment.'),
(33,'master-data-ui','Reference code lists','Understand shared reference code lists','Code lists provide stable codes and labels for values used across services.','Choose the relevant reference dataset.\nCheck the code, label and parent value where applicable.\nConfirm the version or effective date if the installed service provides them.','Master-data viewing access.','Use the approved code rather than inventing a free-text value.','Newer catalogue versioning is documented upstream; this installation may expose the earlier attribute/value interface.'),
(34,'master-data-ui','Geography changes','Plan administrative geography changes','Upstream catalogue guidance treats hierarchy and boundaries as a consistent geography version.','Identify the official change and its effective date.\nCheck affected parent and child units.\nPrepare an old-to-new code mapping for reports and consumers.\nUse the authorised reference-data change process.','Approved geographic reference information and administration authority.','Validate consuming forms and maps after the change.','Do not overwrite a household’s recorded LGA merely because its state or a boundary label changes.'),
(35,'master-data-ui','Reference data change review','Review changes to shared reference data','Newer catalogue guidance uses drafts and approvals before publishing versioned changes.','Identify the proposed change and its owner.\nReview the affected values and consumers.\nSubmit through the change controls available in the installed release.','Reference-data change authority.','Confirm the published values and their effective date.','Do not assume draft/publish controls exist in older interfaces; ask the administrator to confirm the supported process.'),
(36,'master-data-ui','Reference data navigation','Navigate the reference-data administration interface','The current upstream catalogue UI groups datasets, geography, releases and activity.','Identify the installed interface and its menu labels.\nLocate the dataset or geography entry you need.\nInspect codes, labels and available history before proposing changes.','Master-data access.','Use the authorised edit or review process for the selected item.','The local version may use Attributes and Values rather than the newer catalogue pages.'),
(37,'awe','Approval patterns','Understand approval stages and quorum','Approval policies can combine sequential stages, parallel groups and required approval counts.','Identify the request’s active policy.\nCheck the current stage and assigned approvers.\nDetermine whether all, a configured count or a percentage must approve.','Request-view permission and a configured policy.','Complete your assigned task and monitor the next stage.','Your individual approval may not complete the stage; newer policy options may not exist in this release.'),
(38,'awe','Policy versions','Understand approval policy versions','A policy defines stages and rules; requests can remain tied to the version they started with.','Inspect the policy version attached to the request.\nCompare its stage rules with the active configuration.\nPrepare changes in a new draft where that versioning interface is available.','Approval administration authority for configuration changes.','Test the revised policy before activation.','Changing a policy does not necessarily change requests already in progress.'),
(39,'awe','Overdue approval tasks','Understand overdue task escalation','An SLA policy determines what happens when an assigned task passes its due time.','Check the due time and current stage.\nInspect the configured breach action.\nContact the responsible supervisor through the approved escalation process.','Task-view access; administrative authority to change policies.','Track the actual escalation result in request history.','An overdue task is not automatically approved. Upstream permits several actions; confirm this deployment’s configured behaviour.'),
(40,'awe','Independent approvers','Understand separation of approval duties','Policy settings can prevent requesters or earlier-stage approvers from approving later work.','Check your relationship to the request.\nReview the available assigned task.\nUse the independent reviewer route required by the policy.','Assigned approver permission.','Escalate a stage with no eligible approver.','A role alone may not make you eligible for every task; do not bypass separation rules by changing accounts.'),
(41,'awe','Task reassignment','Understand reassignment of a blocked approval task','The documented admin workflow closes the old task and creates one for a new assignee.','Open the request and locate the unresolved task.\nConfirm why reassignment is needed and who is authorised to receive it.\nHave an authorised administrator use Reassign if available.\nCheck the resulting task and audit entry.','Approval administrator permission.','The new assignee reviews the task.','Reassignment is not approval. The original due time may remain in effect.'),
(42,'partner-management','Partner lifecycle and keys','Understand partner onboarding and public keys','Partner management stores partner identity, lifecycle and signing public keys.','Check the stable partner identifier and organisation.\nInspect the onboarding request and proposed public keys.\nUse the authorised review process to activate or reject the request.','Partner administration and review permission.','Verify the partner and key status for the intended integration.','A created partner or pending key is not automatically active. Never put private keys in guidance or uploaded public-key fields.'),
(43,'partner-management','Partner key integration','Understand partner signature verification','Integrations can retrieve active partner public keys from partner management.','Confirm that the caller’s partner identifier matches the onboarded identifier.\nCheck partner activation and key validity.\nAsk the integration administrator to inspect key retrieval and signature failures.','An approved integration and its responsible administrator.','Retest an authorised fictional request.','Disabled or unknown partners must not be treated as trusted merely because a prior key is cached.'),
(44,'consent-manager','Consent decision enforcement','Understand effective consent scope','Documented consent decisions restrict sharing to the intersection of requested, granted and policy-permitted data.','Check the subject, recipient, purpose and requested fields.\nReview the validation result and effective scopes.\nRelease data only through a configured enforcement integration.','Consent-policy access and a supported integration.','Retain the decision reference or resolve the denial.','A broad request does not authorise broad sharing; upstream design details may differ from the installed implementation.'),
(45,'consent-manager','Partner policy scope','Understand consent policies for partners','A consent policy limits what a partner can receive from a specified data controller.','Identify the partner and controller.\nReview the permitted purpose, scopes and validity constraints.\nSend policy changes through the authorised approval process.','Consent administration authority.','Test the resulting decision using fictional subjects.','Newer documentation separates partner identity from consent bindings. Confirm this deployment’s version before applying those screens.'),
(46,'consent-manager','Consent withdrawal and expiry','Understand consent lifecycle and withdrawal','Consent can progress through request, authentication, grant, expiry or revocation.','Review who is requesting data and why.\nUse the configured subject consent flow to grant or decline.\nCheck active status and expiry before use.\nUse the authorised revocation route when withdrawing a grant.','A configured consent flow and the appropriate subject or administrative authority.','Check the receipt and updated status where supported.','A pending request is not an active grant. Consent collection and registry enforcement may use different integration paths.'),
(47,'superset','Dashboard import preparation','Prepare a dashboard import','Superset can import packaged dashboard definitions linked to configured datasets.','Have an authorised analytics administrator confirm the target data connection.\nChoose a compatible dashboard ZIP package.\nImport through the available dashboard controls.\nOpen the result and check every chart and filter.','Dashboard import permission and an approved data connection.','Validate counts against the source dataset.','Never paste database credentials into help text; imported charts may require connection or schema corrections.'),
]
articles=[]
for idx,module,stage,title,purpose,steps,requirements,next_step,issues in rows:
 ref=refs[idx]
 articles.append(dict(slug='docs-'+module+'-'+Path(ref['path']).stem,module=module,stage=stage,audience='all',title=title,purpose=purpose,steps=steps,requirements=requirements,next_step=next_step,issues=issues,sources=[dict(title='OpenG2P documentation: '+Path(ref['path']).stem.replace('-',' '),url=ref['url'])],scope='upstream_reference',sources_checked_on='2026-10-05',origin='system:documentation-import'))
(P/'documentation-pack.json').write_text(json.dumps({'schema_version':1,'articles':articles},ensure_ascii=False,indent=2),encoding='utf-8')
print('Authored',len(articles),'source-linked task articles')
